  abortedText: Object.freeze({ hex: '#9C9686', ansi256: 246 }),
  errorText: Object.freeze({ hex: '#E4342F', ansi256: 160 }),
  onTheHouseText: Object.freeze({ hex: '#E9BD7F', ansi256: 180, dim: true }),
